/* From Uiverse.io by vinodjangid07  - Tags: slider, animation, switch, toggle, click effect */
/* To hide the checkbox */
.__UIV_SCOPE__ #checkboxInput {
  display: none;
}

.__UIV_SCOPE__ .toggleSwitch {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  width: 50px;
  height: 30px;
  background-color: rgb(112, 112, 112);
  border-radius: 20px;
  cursor: pointer;
  transition-duration: 0.2s;
}

.__UIV_SCOPE__ .slider {
  height: 20px;
  position: absolute;
  left: 5px;
  border-radius: 50%;
  transition-duration: 0.2s;
  border: 3px solid rgb(71, 71, 71);
  background-color: rgb(71, 71, 71);
  fill: rgb(255, 129, 129);
}

.__UIV_SCOPE__ #checkboxInput:checked + .toggleSwitch .slider {
  transform: translateX(100%);
  transition-duration: 0.2s;
  fill: rgb(94, 255, 1);
}
/* Switch background change */
.__UIV_SCOPE__ #checkboxInput:checked + .toggleSwitch {
  /* background-color: rgb(148, 118, 255); */
  transition-duration: 0.2s;
}
